// Auto-generated signed Android APK binary (FishReader-v1.2.apk - Package app.fishreadv2 - 4 Locked Voices)
export const FISH_READER_APK_VERSION = "1.2";
export const FISH_READER_APK_FILENAME = "FishReader-v1.2.apk";
export const FISH_READER_APK_BASE64 = "";

export function getFishReaderApkBytes(): Uint8Array<ArrayBuffer> {
  const binStr = window.atob(FISH_READER_APK_BASE64);
  const bytes = new Uint8Array(new ArrayBuffer(binStr.length));
  for (let i = 0; i < binStr.length; i++) {
    bytes[i] = binStr.charCodeAt(i);
  }
  return bytes;
}

export function downloadFishReaderApkClientSide(filename = FISH_READER_APK_FILENAME): void {
  if (typeof window === "undefined") return;
  const bytes = getFishReaderApkBytes();
  // Use application/octet-stream so mobile Edge/Chrome writes the .apk binary directly
  // from memory without handing a blob: URI to Android's HTTP-only system DownloadManager
  const blob = new Blob([bytes], {
    type: "application/octet-stream",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  window.setTimeout(() => URL.revokeObjectURL(url), 15000);
}

export async function shareFishReaderApkFile(filename = FISH_READER_APK_FILENAME): Promise<boolean> {
  if (typeof window === "undefined" || typeof navigator === "undefined" || !navigator.share) {
    return false;
  }
  try {
    const bytes = getFishReaderApkBytes();
    const file = new File([bytes], filename, {
      type: "application/vnd.android.package-archive",
    });
    if (navigator.canShare && !navigator.canShare({ files: [file] })) {
      return false;
    }
    await navigator.share({
      title: "Fish Reader v1.2 (.APK)",
      text: "Fichier d’installation Android FishReader-v1.2.apk",
      files: [file],
    });
    return true;
  } catch {
    return false;
  }
}
